//! Network (graph) container.

use super::link::norm_key;
use super::{Link, Node, NodeId};
use indexmap::{IndexMap, IndexSet};
use serde::{Deserialize, Serialize};
use std::collections::HashSet;

/// Adjacency index for node-to-link lookup.
#[derive(Debug, Clone, Default)]
pub struct AdjacencyIndex {
    pub by_node: IndexMap<NodeId, Vec<usize>>,
    pub is_built: bool,
}

/// Network metadata.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct NetworkMetadata {
    pub is_directed: bool,
    pub is_bipartite: Option<bool>,
    pub is_dag: Option<bool>,
    pub name: Option<String>,
    pub description: Option<String>,
}

/// Network (graph) containing nodes and links.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct Network {
    #[serde(with = "indexmap::map::serde_seq")]
    nodes: IndexMap<NodeId, Node>,
    links: Vec<Link>,
    lone_nodes: IndexSet<NodeId>,
    #[serde(default)]
    pub metadata: NetworkMetadata,
    #[serde(skip)]
    adjacency: AdjacencyIndex,
}

impl Network {
    /// Create a new empty network.
    pub fn new() -> Self {
        Self::default()
    }

    /// Create a network with pre-allocated capacity.
    pub fn with_capacity(node_capacity: usize, link_capacity: usize) -> Self {
        Self {
            nodes: IndexMap::with_capacity(node_capacity),
            links: Vec::with_capacity(link_capacity),
            lone_nodes: IndexSet::with_capacity(node_capacity),
            metadata: NetworkMetadata::default(),
            adjacency: AdjacencyIndex::default(),
        }
    }

    // =========================================================================
    // Node operations
    // =========================================================================

    /// Add a node to the network.
    pub fn add_node(&mut self, node: Node) {
        self.nodes.entry(node.id.clone()).or_insert(node);
        self.invalidate_adjacency();
    }

    /// Add a node by ID, creating a Node if it doesn't exist.
    pub fn add_node_by_id(&mut self, id: impl Into<NodeId>) -> &Node {
        let id = id.into();
        self.nodes.entry(id.clone()).or_insert_with(|| Node::new(id));
        self.invalidate_adjacency();
        // Borrow checker workaround:
        self.nodes.get(&id).unwrap()
    }

    /// Get a node by its ID.
    pub fn get_node(&self, id: &NodeId) -> Option<&Node> {
        self.nodes.get(id)
    }

    /// Check if a node exists in the network.
    pub fn contains_node(&self, id: &NodeId) -> bool {
        self.nodes.contains_key(id)
    }

    /// Get the number of nodes.
    pub fn node_count(&self) -> usize {
        self.nodes.len()
    }

    /// Iterate over all nodes.
    pub fn nodes(&self) -> impl Iterator<Item = &Node> {
        self.nodes.values()
    }

    /// Iterate over all node IDs.
    pub fn node_ids(&self) -> impl Iterator<Item = &NodeId> {
        self.nodes.keys()
    }

    /// Add a lone node (a node with no edges).
    pub fn add_lone_node(&mut self, id: impl Into<NodeId>) {
        let id = id.into();
        self.nodes.entry(id.clone()).or_insert_with(|| Node::new(id.clone()));
        self.lone_nodes.insert(id);
        self.invalidate_adjacency();
    }

    /// Get lone nodes (nodes with no edges).
    pub fn lone_nodes(&self) -> &IndexSet<NodeId> {
        &self.lone_nodes
    }

    // =========================================================================
    // Link operations
    // =========================================================================

    /// Add a link to the network.
    pub fn add_link(&mut self, link: Link) {
        // Ensure both endpoints exist as nodes:
        self.nodes
            .entry(link.source.clone())
            .or_insert_with(|| Node::new(link.source.clone()));
        self.nodes
            .entry(link.target.clone())
            .or_insert_with(|| Node::new(link.target.clone()));
        self.links.push(link);
        self.invalidate_adjacency();
    }

    /// Get the number of links.
    pub fn link_count(&self) -> usize {
        self.links.len()
    }

    /// Iterate over all links.
    pub fn links(&self) -> impl Iterator<Item = &Link> {
        self.links.iter()
    }

    /// Get links as a slice.
    pub fn links_slice(&self) -> &[Link] {
        &self.links
    }

    /// Get mutable access to links.
    pub fn links_mut(&mut self) -> &mut Vec<Link> {
        &mut self.links
    }

    // =========================================================================
    // Query operations
    // =========================================================================

    /// Get all links incident to a node (as source or target).
    pub fn links_for_node(&self, node_id: &NodeId) -> Vec<&Link> {
        self.links
            .iter()
            .filter(|l| &l.source == node_id || &l.target == node_id)
            .collect()
    }

    /// Get the degree of a node (number of incident links).
    pub fn degree(&self, node_id: &NodeId) -> usize {
        self.links
            .iter()
            .filter(|l| &l.source == node_id || &l.target == node_id)
            .count()
    }

    /// Get neighbors of a node.
    pub fn neighbors(&self, node_id: &NodeId) -> HashSet<&NodeId> {
        let mut out: HashSet<&NodeId> = HashSet::new();
        for l in &self.links {
            if &l.source == node_id {
                out.insert(&l.target);
            }
            if &l.target == node_id {
                out.insert(&l.source);
            }
        }
        out
    }

    /// Get all unique relation types in the network.
    pub fn relation_types(&self) -> HashSet<&str> {
        self.links.iter().map(|l| l.relation.as_str()).collect()
    }

    /// Get a node mutably by ID.
    pub fn get_node_mut(&mut self, id: &NodeId) -> Option<&mut Node> {
        self.nodes.get_mut(id)
    }

    /// Set an attribute on a node (convenience wrapper).
    pub fn set_node_attribute(
        &mut self,
        node_id: &NodeId,
        key: impl Into<String>,
        value: impl Into<String>,
    ) -> bool {
        if let Some(node) = self.nodes.get_mut(node_id) {
            node.set_attribute(key, value);
            true
        } else {
            false
        }
    }

    // =========================================================================
    // Shadow link generation
    // =========================================================================

    /// Generate shadow links for all non-feedback, non-shadow links.
    ///
    /// Returns the number of shadow links added.
    pub fn generate_shadows(&mut self) -> usize {
        let new_shadows: Vec<Link> = self
            .links
            .iter()
            .filter(|l| !l.is_shadow && !l.is_feedback())
            .filter_map(|l| l.to_shadow())
            .filter(|s| !self.links.iter().any(|e| e == s))
            .collect();
        let count = new_shadows.len();
        for s in new_shadows {
            self.add_link(s);
        }
        count
    }

    /// Check whether shadow links have already been generated.
    pub fn has_shadows(&self) -> bool {
        self.links.iter().any(|l| l.is_shadow)
    }

    /// Count of shadow links in the network.
    pub fn shadow_count(&self) -> usize {
        self.links.iter().filter(|l| l.is_shadow).count()
    }

    /// Count of non-shadow links.
    pub fn regular_link_count(&self) -> usize {
        self.links.iter().filter(|l| !l.is_shadow).count()
    }

    // =========================================================================
    // Adjacency index
    // =========================================================================

    fn invalidate_adjacency(&mut self) {
        self.adjacency.is_built = false;
    }

    /// Access the adjacency index if it has been built.
    pub fn adjacency_index(&self) -> Option<&IndexMap<NodeId, Vec<usize>>> {
        if self.adjacency.is_built {
            Some(&self.adjacency.by_node)
        } else {
            None
        }
    }

    /// Rebuild the adjacency index.
    pub fn rebuild_adjacency_index(&mut self) {
        let mut by_node: IndexMap<NodeId, Vec<usize>> = IndexMap::new();
        for (i, l) in self.links.iter().enumerate() {
            by_node.entry(l.source.clone()).or_default().push(i);
            by_node.entry(l.target.clone()).or_default().push(i);
        }
        self.adjacency = AdjacencyIndex {
            by_node,
            is_built: true,
        };
    }

    /// Whether the adjacency index is built and valid.
    pub fn has_adjacency_index(&self) -> bool {
        self.adjacency.is_built
    }

    // =========================================================================
    // Metadata detection
    // =========================================================================

    /// Detect whether the network contains directed edges and update metadata.
    pub fn detect_directed(&mut self) {
        self.metadata.is_directed = self.links.iter().any(|l| l.directed == Some(true));
    }

    /// Detect whether the network is bipartite (two-colorable) and update metadata.
    pub fn detect_bipartite(&mut self) -> bool {
        // Build undirected adjacency over non-shadow links:
        let mut adj: IndexMap<NodeId, Vec<NodeId>> = IndexMap::new();
        for l in &self.links {
            if l.is_shadow {
                continue;
            }
            adj.entry(l.source.clone()).or_default().push(l.target.clone());
            adj.entry(l.target.clone()).or_default().push(l.source.clone());
        }
        let mut color: IndexMap<NodeId, i32> = IndexMap::new();
        let is_bip = match self.two_color(&adj, &mut color) {
            Ok(()) => true,
            Err(()) => false,
        };
        self.metadata.is_bipartite = Some(is_bip);
        is_bip
    }

    fn two_color(
        &self,
        adj: &IndexMap<NodeId, Vec<NodeId>>,
        color: &mut IndexMap<NodeId, i32>,
    ) -> Result<(), ()> {
        // Visit nodes in network order:
        for n in self.nodes.keys() {
            if color.contains_key(n) {
                continue;
            }
            color.insert(n.clone(), 0);
            let mut stack = vec![n.clone()];
            while let Some(u) = stack.pop() {
                let cu = *color.get(&u).unwrap();
                if let Some(nbrs) = adj.get(&u) {
                    for v in nbrs {
                        match color.get(v) {
                            None => {
                                color.insert(v.clone(), 1 - cu);
                                stack.push(v.clone());
                            }
                            Some(&cv) => {
                                if cv == cu {
                                    return Err(());
                                }
                            }
                        }
                    }
                }
            }
        }
        Ok(())
    }

    /// Detect whether the network is a DAG and update metadata.
    pub fn detect_dag(&mut self) -> bool {
        // Treat links with directed == Some(true) as directed edges; everything
        // else is undirected (and thus not a DAG if it has any edge).
        let has_directed = self.links.iter().any(|l| l.directed == Some(true));
        let is_dag = if has_directed {
            // Kahn's algorithm on directed edges only:
            let mut indeg: IndexMap<NodeId, usize> = IndexMap::new();
            let mut adj: IndexMap<NodeId, Vec<NodeId>> = IndexMap::new();
            for l in &self.links {
                if l.directed == Some(true) && !l.is_shadow {
                    *indeg.entry(l.target.clone()).or_insert(0) += 1;
                    adj.entry(l.source.clone()).or_default().push(l.target.clone());
                }
            }
            for n in self.nodes.keys() {
                indeg.entry(n.clone()).or_insert(0);
            }
            let mut queue: Vec<NodeId> = indeg
                .iter()
                .filter(|(_, &d)| d == 0)
                .map(|(n, _)| n.clone())
                .collect();
            let mut visited = 0usize;
            while let Some(u) = queue.pop() {
                visited += 1;
                if let Some(nbrs) = adj.get(&u) {
                    for v in nbrs {
                        if let Some(d) = indeg.get_mut(v) {
                            *d -= 1;
                            if *d == 0 {
                                queue.push(v.clone());
                            }
                        }
                    }
                }
            }
            visited == self.nodes.len()
        } else {
            // No directed edges: a DAG only if there are no edges at all.
            self.links.iter().all(|l| l.is_shadow) || self.links.is_empty()
        };
        self.metadata.is_dag = Some(is_dag);
        is_dag
    }

    // =========================================================================
    // Selection propagation helpers
    // =========================================================================

    /// Get nodes within N hops of a given node (BFS neighborhood).
    pub fn n_hop_neighborhood(&self, start: &NodeId, max_hops: usize) -> HashSet<NodeId> {
        let mut result: HashSet<NodeId> = HashSet::new();
        let mut frontier: HashSet<NodeId> = HashSet::new();
        frontier.insert(start.clone());
        for _ in 0..max_hops {
            let next = self.first_neighbors(&frontier);
            if next.is_empty() {
                break;
            }
            let added: Vec<_> = next.into_iter().filter(|n| !result.contains(n) && n != start).collect();
            if added.is_empty() {
                break;
            }
            for n in &added {
                result.insert(n.clone());
            }
            frontier = added.into_iter().collect();
        }
        result
    }

    /// Get the first neighbors (1-hop) of a set of nodes.
    pub fn first_neighbors(&self, nodes: &HashSet<NodeId>) -> HashSet<NodeId> {
        let mut out: HashSet<NodeId> = HashSet::new();
        for l in &self.links {
            if nodes.contains(&l.source) {
                out.insert(l.target.clone());
            }
            if nodes.contains(&l.target) {
                out.insert(l.source.clone());
            }
        }
        out
    }

    // =========================================================================
    // Subnetwork extraction
    // =========================================================================

    /// Extract a subnetwork containing only the specified nodes.
    pub fn extract_subnetwork(&self, node_ids: &HashSet<NodeId>) -> Network {
        let mut sub = Network::new();
        // Preserve original node order for the selected nodes:
        for n in self.nodes.keys() {
            if node_ids.contains(n) {
                sub.add_node(Node::new(n.clone()));
            }
        }
        for l in &self.links {
            if node_ids.contains(&l.source) && node_ids.contains(&l.target) {
                sub.add_link(l.clone());
            }
        }
        // Lone nodes of the subnetwork:
        for n in sub.nodes.keys() {
            if sub.degree(n) == 0 {
                sub.lone_nodes.insert(n.clone());
            }
        }
        sub.metadata = self.metadata.clone();
        sub
    }

    /// Extract the subnetwork reachable within N hops of a starting node.
    pub fn extract_neighborhood(&self, start: &NodeId, max_hops: usize) -> Network {
        let mut keep: HashSet<NodeId> = HashSet::new();
        keep.insert(start.clone());
        keep.extend(self.n_hop_neighborhood(start, max_hops));
        self.extract_subnetwork(&keep)
    }

    // =========================================================================
    // Link deduplication
    // =========================================================================

    /// Remove duplicate and synonymous non-directional links.
    ///
    /// Mirrors `BuildExtractorImpl.preprocessLinks`: exact duplicates are
    /// dropped, and for synonymous undirected pairs the lexicographically
    /// smaller orientation is kept.
    pub fn deduplicate_links(&mut self) -> usize {
        let original = std::mem::take(&mut self.links);
        self.invalidate_adjacency();
        let mut retained: Vec<Link> = Vec::new();

        for next in &original {
            let already = retained.iter().any(|r| r == next);
            if already {
                continue;
            }
            let is_dir = next.directed == Some(true);
            if !is_dir && !next.is_feedback() {
                let flip = next.flipped();
                if retained.iter().any(|r| r == &flip) {
                    // Keep lex-smaller orientation:
                    if link_compare(next, &flip) < 0 {
                        // replace flip with next
                        if let Some(pos) = retained.iter().position(|r| r == &flip) {
                            retained.remove(pos);
                        }
                        retained.push(next.clone());
                    }
                    // else: drop next
                } else {
                    retained.push(next.clone());
                }
            } else {
                retained.push(next.clone());
            }
        }

        let removed = original.len() - retained.len();
        self.links = retained;
        removed
    }

    // =========================================================================
    // Comparison utilities
    // =========================================================================

    /// Compare the neighborhoods of two nodes.
    pub fn compare_nodes(
        &self,
        node_a: &NodeId,
        node_b: &NodeId,
    ) -> Option<NodeComparison> {
        if !self.contains_node(node_a) || !self.contains_node(node_b) {
            return None;
        }
        let neighbors_of = |n: &NodeId| -> HashSet<NodeId> {
            let mut s: HashSet<NodeId> = HashSet::new();
            for l in &self.links {
                if &l.source == n {
                    s.insert(l.target.clone());
                }
                if &l.target == n {
                    s.insert(l.source.clone());
                }
            }
            s
        };
        let a_nbr = neighbors_of(node_a);
        let b_nbr = neighbors_of(node_b);
        let shared: HashSet<NodeId> = a_nbr.intersection(&b_nbr).cloned().collect();
        let excl_a: HashSet<NodeId> = a_nbr.difference(&b_nbr).cloned().collect();
        let excl_b: HashSet<NodeId> = b_nbr.difference(&a_nbr).cloned().collect();
        let union_size = a_nbr.union(&b_nbr).count();
        let jaccard = if union_size == 0 {
            0.0
        } else {
            shared.len() as f64 / union_size as f64
        };
        Some(NodeComparison {
            node_a: node_a.clone(),
            node_b: node_b.clone(),
            degree_a: a_nbr.len(),
            degree_b: b_nbr.len(),
            shared_neighbors: shared,
            exclusive_a: excl_a,
            exclusive_b: excl_b,
            jaccard_similarity: jaccard,
        })
    }
}

/// Lexicographic comparison of two links, matching Java's `LinkComparator`.
fn link_compare(a: &Link, b: &Link) -> std::cmp::Ordering {
    use std::cmp::Ordering;
    if a == b {
        return Ordering::Equal;
    }
    let sa = norm_key(a.source.as_str());
    let sb = norm_key(b.source.as_str());
    if sa != sb {
        return sa.cmp(&sb);
    }
    let ta = norm_key(a.target.as_str());
    let tb = norm_key(b.target.as_str());
    if ta != tb {
        return ta.cmp(&tb);
    }
    if a.is_shadow != b.is_shadow {
        return if a.is_shadow {
            Ordering::Less
        } else {
            Ordering::Greater
        };
    }
    let ra = norm_key(&a.relation);
    let rb = norm_key(&b.relation);
    if ra != rb {
        return a.relation.cmp(&b.relation);
    }
    a.source.as_str().cmp(b.source.as_str())
}

/// Neighborhood comparison result.
#[derive(Debug, Clone)]
pub struct NodeComparison {
    pub node_a: NodeId,
    pub node_b: NodeId,
    pub degree_a: usize,
    pub degree_b: usize,
    pub shared_neighbors: HashSet<NodeId>,
    pub exclusive_a: HashSet<NodeId>,
    pub exclusive_b: HashSet<NodeId>,
    pub jaccard_similarity: f64,
}

